"""Transcribe connector-visible source fields; no geometric processing.
All triple rows are x, top_y, bottom_y for the observed shared-x pair.
Regular source p labels are expanded from their observed source indices.
See source_receipts.json for remote blob and ranges. Not a new source authority.
"""
import json, pathlib, hashlib
ROOT=pathlib.Path(__file__).resolve().parents[1]

FIELDS=['id','worker','points','condition','independent','independence_reasons','consensus_eligible','quality_candidate','main_quality_gate','main_consensus_gate','source_point_indices','source_point_labels','source_pair_indices','order_status','order_used','ring_confirmed','preprocessing_status','borrowed_points','cleaning','image','evidence_kind']

def make(image, rid, worker, triples, indices, pairids=None, confirmed=True):
    return dict(id=rid,worker=worker,points=[[x,y] for x,t,b in triples for y in (t,b)],condition='manual',independent=True,independence_reasons=[],consensus_eligible=True,quality_candidate=True,main_quality_gate={'status':'candidate_pending_geometry','reasons':[]},main_consensus_gate={'status':'main_candidate','reasons':['main_candidate'],'scope_policy':'retain_scope_variation'},source_point_indices=indices,source_point_labels=[f'p{i+1}' for i in indices],source_pair_indices=list(range(len(triples))) if pairids is None else pairids,order_status='human_confirmed' if confirmed else 'default_unreviewed',order_used='human_confirmed' if confirmed else 'default_x_unreviewed',ring_confirmed=confirmed,preprocessing_status='ready',borrowed_points=False,cleaning='retained',image=image,evidence_kind='human_observed')

def save(image, records):
    panel=dict(image=image,condition='manual',evidence_kind='human_observed',records=records)
    b=(json.dumps(panel,ensure_ascii=False,indent=2)+'\n').encode()
    (ROOT/'inputs'/f'{image}.json').write_bytes(b)
    sha=hashlib.sha1(b'blob '+str(len(b)).encode()+b'\0'+b).hexdigest()
    print(image,len(records),len(b),sha)
    return panel

